ALTER TABLE public.financeiro_baixas ADD COLUMN IF NOT EXISTS estorno_de_id uuid REFERENCES public.financeiro_baixas(id);
CREATE UNIQUE INDEX IF NOT EXISTS financeiro_baixas_estorno_unico ON public.financeiro_baixas(estorno_de_id) WHERE estorno_de_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.registrar_baixa(p_tipo text,p_lancamento uuid,p_valor numeric,p_conta uuid,p_forma uuid DEFAULT NULL,p_data date DEFAULT current_date,p_juros numeric DEFAULT 0,p_multa numeric DEFAULT 0,p_desconto numeric DEFAULT 0,p_caixa uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_clinica uuid;v_unidade uuid;v_status lancamento_status;v_total numeric(12,2);v_pago numeric(12,2);v_id uuid;BEGIN IF NOT(tem_papel('owner','admin','financeiro') OR(p_tipo='receber' AND tem_papel('recepcao') AND coalesce(p_data,current_date)=current_date AND p_caixa IS NOT NULL))THEN RAISE EXCEPTION 'Sem permissão para registrar esta baixa';END IF;IF p_tipo='receber'THEN SELECT clinica_id,unidade_id,status,valor,valor_pago INTO v_clinica,v_unidade,v_status,v_total,v_pago FROM financeiro_recebimentos WHERE id=p_lancamento FOR UPDATE;ELSIF p_tipo='pagar'THEN SELECT clinica_id,unidade_id,status,valor,valor_pago INTO v_clinica,v_unidade,v_status,v_total,v_pago FROM financeiro_pagamentos WHERE id=p_lancamento FOR UPDATE;ELSE RAISE EXCEPTION 'Tipo inválido';END IF;IF v_clinica IS NULL OR v_clinica<>current_clinica_id()THEN RAISE EXCEPTION 'Lançamento não encontrado';END IF;IF v_status='cancelado'OR v_pago>=v_total THEN RAISE EXCEPTION 'Lançamento não está em aberto';END IF;IF round(coalesce(p_valor,0),2)<=0 OR round(p_valor,2)>round(v_total-v_pago,2)THEN RAISE EXCEPTION 'Valor da baixa inválido';END IF;IF NOT EXISTS(SELECT 1 FROM contas_financeiras WHERE id=p_conta AND clinica_id=v_clinica AND ativo)THEN RAISE EXCEPTION 'Conta financeira inválida';END IF;IF p_forma IS NOT NULL AND NOT EXISTS(SELECT 1 FROM formas_pagamento WHERE id=p_forma AND clinica_id=v_clinica AND ativo)THEN RAISE EXCEPTION 'Forma de pagamento inválida';END IF;IF p_caixa IS NOT NULL AND NOT EXISTS(SELECT 1 FROM caixa_sessoes WHERE id=p_caixa AND clinica_id=v_clinica AND status='aberto'AND unidade_id IS NOT DISTINCT FROM v_unidade AND(operador_id=auth.uid()OR tem_papel('owner','admin','financeiro')))THEN RAISE EXCEPTION 'Caixa não está aberto para esta unidade';END IF;INSERT INTO financeiro_baixas(clinica_id,unidade_id,recebimento_id,pagamento_id,conta_financeira_id,forma_pagamento_id,valor,juros,multa,desconto,pago_em,caixa_sessao_id)VALUES(v_clinica,v_unidade,CASE WHEN p_tipo='receber'THEN p_lancamento END,CASE WHEN p_tipo='pagar'THEN p_lancamento END,p_conta,p_forma,round(p_valor,2),round(coalesce(p_juros,0),2),round(coalesce(p_multa,0),2),round(coalesce(p_desconto,0),2),coalesce(p_data,current_date),p_caixa)RETURNING id INTO v_id;PERFORM atualizar_totais_lancamento(p_tipo,p_lancamento);RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.estornar_baixa(p_baixa uuid,p_motivo text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b financeiro_baixas%ROWTYPE;v_id uuid;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão para estornar';END IF;IF length(trim(coalesce(p_motivo,'')))<5 THEN RAISE EXCEPTION 'Informe o motivo do estorno';END IF;SELECT * INTO b FROM financeiro_baixas WHERE id=p_baixa FOR UPDATE;IF NOT FOUND OR b.clinica_id<>current_clinica_id()OR b.tipo<>'baixa'THEN RAISE EXCEPTION 'Baixa não encontrada';END IF;IF EXISTS(SELECT 1 FROM financeiro_baixas WHERE estorno_de_id=b.id)THEN RAISE EXCEPTION 'Baixa já estornada';END IF;INSERT INTO financeiro_baixas(clinica_id,unidade_id,recebimento_id,pagamento_id,conta_financeira_id,forma_pagamento_id,valor,juros,multa,desconto,tipo,motivo,pago_em,estorno_de_id)VALUES(b.clinica_id,b.unidade_id,b.recebimento_id,b.pagamento_id,b.conta_financeira_id,b.forma_pagamento_id,b.valor,b.juros,b.multa,b.desconto,'estorno',trim(p_motivo),current_date,b.id)RETURNING id INTO v_id;PERFORM atualizar_totais_lancamento(CASE WHEN b.recebimento_id IS NOT NULL THEN 'receber'ELSE'pagar'END,coalesce(b.recebimento_id,b.pagamento_id));RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.fechar_caixa(p_sessao uuid,p_saldo_informado numeric,p_conferencia jsonb,p_justificativa text DEFAULT NULL)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE s caixa_sessoes%ROWTYPE;v_calc numeric(12,2);v_dif numeric(12,2);BEGIN SELECT * INTO s FROM caixa_sessoes WHERE id=p_sessao FOR UPDATE;IF NOT FOUND OR s.clinica_id<>current_clinica_id()OR s.status<>'aberto'THEN RAISE EXCEPTION 'Caixa não está aberto';END IF;IF NOT(tem_papel('owner','admin','financeiro')OR(tem_papel('recepcao')AND s.operador_id=auth.uid()))THEN RAISE EXCEPTION 'Sem permissão';END IF;SELECT s.saldo_inicial+coalesce((SELECT sum(CASE WHEN tipo='suprimento'THEN valor ELSE-valor END)FROM caixa_movimentos WHERE sessao_id=s.id),0)+coalesce((SELECT sum(CASE WHEN b.recebimento_id IS NOT NULL THEN(CASE WHEN b.tipo='baixa'THEN 1 ELSE-1 END)*(b.valor+b.juros+b.multa-b.desconto)ELSE(CASE WHEN b.tipo='baixa'THEN-1 ELSE 1 END)*(b.valor+b.juros+b.multa-b.desconto)END)FROM financeiro_baixas b WHERE b.caixa_sessao_id=s.id),0)INTO v_calc;v_dif:=round(coalesce(p_saldo_informado,0)-v_calc,2);IF v_dif<>0 AND length(trim(coalesce(p_justificativa,'')))<5 THEN RAISE EXCEPTION 'Informe a justificativa da diferença';END IF;UPDATE caixa_sessoes SET fechado_em=now(),saldo_informado=round(p_saldo_informado,2),saldo_calculado=v_calc,diferenca=v_dif,conferencia=coalesce(p_conferencia,'{}'),justificativa=nullif(trim(p_justificativa),''),status='fechado'WHERE id=s.id;END $$;

CREATE OR REPLACE FUNCTION public.apurar_comissoes(p_competencia date)RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE v_clinica uuid:=current_clinica_id();v_mes date:=date_trunc('month',p_competencia)::date;v_fim date:=(date_trunc('month',p_competencia)+interval'1 month - 1 day')::date;a record;v_ap uuid;v_n integer:=0;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão para apurar comissões';END IF;FOR a IN SELECT p.id profissional_id,p.unidade_id FROM profissionais p WHERE p.clinica_id=v_clinica AND p.ativo AND EXISTS(SELECT 1 FROM regras_comissao r WHERE r.profissional_id=p.id AND r.ativo)LOOP INSERT INTO apuracoes_comissao(clinica_id,unidade_id,profissional_id,competencia,status)VALUES(v_clinica,a.unidade_id,a.profissional_id,v_mes,'rascunho')ON CONFLICT(clinica_id,profissional_id,competencia)DO UPDATE SET unidade_id=excluded.unidade_id WHERE apuracoes_comissao.status='rascunho'RETURNING id INTO v_ap;IF v_ap IS NOT NULL THEN DELETE FROM apuracao_comissao_itens WHERE apuracao_id=v_ap;INSERT INTO apuracao_comissao_itens(clinica_id,apuracao_id,regra_id,recebimento_id,baixa_id,descricao,base_calculo,custo_material,taxa_pagamento,valor_comissao)SELECT v_clinica,v_ap,rc.id,fr.id,b.id,fr.descricao,b.valor,0,b.taxa+b.desconto,round(CASE WHEN rc.tipo_calculo='valor_fixo'THEN rc.valor WHEN rc.tipo_calculo='percentual_liquido'THEN greatest(b.valor-b.taxa-b.desconto,0)*rc.valor/100 ELSE b.valor*rc.valor/100 END,2)FROM financeiro_baixas b JOIN financeiro_recebimentos fr ON fr.id=b.recebimento_id JOIN LATERAL(SELECT rr.* FROM regras_comissao rr WHERE rr.clinica_id=v_clinica AND rr.profissional_id=a.profissional_id AND rr.ativo AND rr.base_apuracao='recebimento'AND(rr.procedimento_id IS NULL OR EXISTS(SELECT 1 FROM orcamento_itens oi WHERE oi.orcamento_id=fr.orcamento_id AND oi.procedimento_id=rr.procedimento_id))AND(rr.especialidade_id IS NULL OR EXISTS(SELECT 1 FROM orcamento_itens oi JOIN procedimentos pr ON pr.id=oi.procedimento_id WHERE oi.orcamento_id=fr.orcamento_id AND pr.especialidade_id=rr.especialidade_id))ORDER BY(rr.procedimento_id IS NOT NULL)DESC,(rr.especialidade_id IS NOT NULL)DESC LIMIT 1)rc ON true WHERE fr.profissional_id=a.profissional_id AND b.tipo='baixa'AND b.pago_em BETWEEN v_mes AND v_fim;UPDATE apuracoes_comissao SET valor_bruto=coalesce((SELECT sum(base_calculo)FROM apuracao_comissao_itens WHERE apuracao_id=v_ap),0),deducoes=coalesce((SELECT sum(custo_material+taxa_pagamento)FROM apuracao_comissao_itens WHERE apuracao_id=v_ap),0),valor_comissao=coalesce((SELECT sum(valor_comissao)FROM apuracao_comissao_itens WHERE apuracao_id=v_ap),0)WHERE id=v_ap;v_n:=v_n+1;END IF;END LOOP;RETURN v_n;END $$;
CREATE OR REPLACE FUNCTION public.mudar_status_comissao(p_apuracao uuid,p_status text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE a apuracoes_comissao%ROWTYPE;v_conta uuid;v_pag uuid;v_nome text;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão';END IF;SELECT * INTO a FROM apuracoes_comissao WHERE id=p_apuracao FOR UPDATE;IF NOT FOUND OR a.clinica_id<>current_clinica_id()THEN RAISE EXCEPTION 'Apuração não encontrada';END IF;IF p_status='conferido'AND a.status='rascunho'THEN UPDATE apuracoes_comissao SET status='conferido',conferido_por=auth.uid(),conferido_em=now()WHERE id=a.id;ELSIF p_status='aprovado'AND a.status='conferido'THEN SELECT nome INTO v_nome FROM profissionais WHERE id=a.profissional_id;SELECT id INTO v_conta FROM plano_contas WHERE clinica_id=a.clinica_id AND natureza='custo_variavel'ORDER BY(nome ILIKE'%comiss%')DESC LIMIT 1;INSERT INTO financeiro_pagamentos(clinica_id,unidade_id,conta_id,fornecedor,descricao,valor,valor_bruto,valor_liquido,vencimento,competencia,origem_tipo,origem_id)VALUES(a.clinica_id,a.unidade_id,v_conta,v_nome,'Comissão profissional — '||to_char(a.competencia,'MM/YYYY'),a.valor_comissao,a.valor_comissao,a.valor_comissao,current_date,a.competencia,'comissao',a.id)RETURNING id INTO v_pag;UPDATE apuracoes_comissao SET status='aprovado',aprovado_por=auth.uid(),aprovado_em=now(),pagamento_id=v_pag WHERE id=a.id;ELSE RAISE EXCEPTION 'Transição de status inválida';END IF;END $$;

CREATE OR REPLACE FUNCTION public.importar_extrato(p_conta uuid,p_nome text,p_formato text,p_itens jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE v_clinica uuid:=current_clinica_id();v_imp uuid;r record;v_n integer:=0;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão';END IF;IF NOT EXISTS(SELECT 1 FROM contas_financeiras WHERE id=p_conta AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Conta inválida';END IF;IF p_formato NOT IN('ofx','csv')THEN RAISE EXCEPTION 'Formato inválido';END IF;INSERT INTO conciliacao_importacoes(clinica_id,conta_financeira_id,nome_arquivo,formato)VALUES(v_clinica,p_conta,p_nome,p_formato)RETURNING id INTO v_imp;FOR r IN SELECT x->>'identificador'identificador,(x->>'data')::date data,x->>'descricao'descricao,round((x->>'valor')::numeric,2)valor FROM jsonb_array_elements(coalesce(p_itens,'[]'))x LOOP IF r.valor<>0 THEN INSERT INTO extrato_bancario_itens(clinica_id,importacao_id,conta_financeira_id,identificador,data,descricao,valor)VALUES(v_clinica,v_imp,p_conta,nullif(r.identificador,''),r.data,r.descricao,r.valor)ON CONFLICT(clinica_id,conta_financeira_id,identificador)WHERE identificador IS NOT NULL DO NOTHING;v_n:=v_n+1;END IF;END LOOP;UPDATE conciliacao_importacoes SET quantidade=v_n WHERE id=v_imp;RETURN v_imp;END $$;
CREATE OR REPLACE FUNCTION public.sugerir_conciliacao(p_extrato uuid)RETURNS TABLE(baixa_id uuid,data date,descricao text,valor numeric,diferenca_dias integer)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT b.id,b.pago_em,coalesce(fr.descricao,fp.descricao),(CASE WHEN b.recebimento_id IS NOT NULL THEN b.valor+b.juros+b.multa-b.desconto ELSE-(b.valor+b.juros+b.multa-b.desconto)END)::numeric,abs(b.pago_em-e.data)::integer FROM extrato_bancario_itens e JOIN financeiro_baixas b ON b.clinica_id=e.clinica_id AND b.conta_financeira_id=e.conta_financeira_id LEFT JOIN financeiro_recebimentos fr ON fr.id=b.recebimento_id LEFT JOIN financeiro_pagamentos fp ON fp.id=b.pagamento_id WHERE e.id=p_extrato AND e.clinica_id=current_clinica_id()AND tem_papel('owner','admin','financeiro')AND b.tipo='baixa'AND abs(b.pago_em-e.data)<=3 AND round(CASE WHEN b.recebimento_id IS NOT NULL THEN b.valor+b.juros+b.multa-b.desconto ELSE-(b.valor+b.juros+b.multa-b.desconto)END,2)=e.valor AND NOT EXISTS(SELECT 1 FROM conciliacoes_bancarias c WHERE c.baixa_id=b.id)ORDER BY abs(b.pago_em-e.data),b.created_at LIMIT 10$$;
CREATE OR REPLACE FUNCTION public.conciliar_extrato(p_extrato uuid,p_baixa uuid,p_observacao text DEFAULT NULL)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE e extrato_bancario_itens%ROWTYPE;b financeiro_baixas%ROWTYPE;v_id uuid;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão';END IF;SELECT * INTO e FROM extrato_bancario_itens WHERE id=p_extrato FOR UPDATE;SELECT * INTO b FROM financeiro_baixas WHERE id=p_baixa;IF e.id IS NULL OR b.id IS NULL OR e.clinica_id<>current_clinica_id()OR b.clinica_id<>e.clinica_id OR b.conta_financeira_id<>e.conta_financeira_id OR e.status<>'pendente'THEN RAISE EXCEPTION 'Dados de conciliação inválidos';END IF;INSERT INTO conciliacoes_bancarias(clinica_id,extrato_item_id,baixa_id,observacao)VALUES(e.clinica_id,e.id,b.id,p_observacao)RETURNING id INTO v_id;UPDATE extrato_bancario_itens SET status='conciliado'WHERE id=e.id;RETURN v_id;END $$;

CREATE OR REPLACE FUNCTION public.relatorio_dre(p_inicio date,p_fim date,p_unidade uuid DEFAULT NULL,p_regime text DEFAULT'competencia')RETURNS TABLE(ordem integer,grupo text,valor numeric)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$WITH cfg AS(SELECT coalesce(max(aliquota_impostos),0)aliq FROM configuracoes_fiscais WHERE clinica_id=current_clinica_id()),rec AS(SELECT coalesce(sum(CASE WHEN p_regime='caixa'THEN r.valor_pago ELSE r.valor_bruto END),0)::numeric v FROM financeiro_recebimentos r WHERE r.clinica_id=current_clinica_id()AND r.status<>'cancelado'AND(p_unidade IS NULL OR r.unidade_id=p_unidade)AND(CASE WHEN p_regime='caixa'THEN coalesce(r.pago_em,r.vencimento)ELSE r.competencia END)BETWEEN p_inicio AND p_fim),desp AS(SELECT coalesce(sum(CASE WHEN p_regime='caixa'THEN p.valor_pago ELSE p.valor_bruto END)FILTER(WHERE pc.natureza='custo_variavel'),0)::numeric cv,coalesce(sum(CASE WHEN p_regime='caixa'THEN p.valor_pago ELSE p.valor_bruto END)FILTER(WHERE pc.natureza='despesa_fixa'),0)::numeric df,coalesce(sum(CASE WHEN p_regime='caixa'THEN p.valor_pago ELSE p.valor_bruto END)FILTER(WHERE pc.natureza IN('despesa_financeira','investimento')),0)::numeric outras FROM financeiro_pagamentos p LEFT JOIN plano_contas pc ON pc.id=p.conta_id WHERE p.clinica_id=current_clinica_id()AND p.status<>'cancelado'AND(p_unidade IS NULL OR p.unidade_id=p_unidade)AND(CASE WHEN p_regime='caixa'THEN coalesce(p.pago_em,p.vencimento)ELSE p.competencia END)BETWEEN p_inicio AND p_fim),vals AS(SELECT rec.v receita,round(rec.v*cfg.aliq/100,2)impostos,desp.cv,desp.df,desp.outras FROM rec CROSS JOIN desp CROSS JOIN cfg)SELECT x.ordem,x.grupo,x.valor FROM(SELECT 1 ordem,'Receita bruta'grupo,receita valor FROM vals UNION ALL SELECT 2,'Impostos estimados',-impostos FROM vals UNION ALL SELECT 3,'Receita líquida',receita-impostos FROM vals UNION ALL SELECT 4,'Custos variáveis',-cv FROM vals UNION ALL SELECT 5,'Margem de contribuição',receita-impostos-cv FROM vals UNION ALL SELECT 6,'Despesas fixas',-df FROM vals UNION ALL SELECT 7,'Resultado operacional',receita-impostos-cv-df FROM vals UNION ALL SELECT 8,'Despesas financeiras e investimentos',-outras FROM vals UNION ALL SELECT 9,'Resultado líquido',receita-impostos-cv-df-outras FROM vals)x WHERE tem_papel('owner','admin','financeiro')ORDER BY x.ordem$$;
CREATE OR REPLACE FUNCTION public.relatorio_fluxo_caixa(p_inicio date,p_fim date,p_unidade uuid DEFAULT NULL)RETURNS TABLE(dia date,entradas numeric,saidas numeric,projetado_entradas numeric,projetado_saidas numeric)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT d::date,coalesce((SELECT sum(CASE WHEN b.tipo='baixa'THEN b.valor+b.juros+b.multa-b.desconto ELSE-(b.valor+b.juros+b.multa-b.desconto)END)FROM financeiro_baixas b JOIN financeiro_recebimentos r ON r.id=b.recebimento_id WHERE b.clinica_id=current_clinica_id()AND b.pago_em=d::date AND(p_unidade IS NULL OR b.unidade_id=p_unidade)),0),coalesce((SELECT sum(CASE WHEN b.tipo='baixa'THEN b.valor+b.juros+b.multa-b.desconto ELSE-(b.valor+b.juros+b.multa-b.desconto)END)FROM financeiro_baixas b JOIN financeiro_pagamentos p ON p.id=b.pagamento_id WHERE b.clinica_id=current_clinica_id()AND b.pago_em=d::date AND(p_unidade IS NULL OR b.unidade_id=p_unidade)),0),coalesce((SELECT sum(r.valor-r.valor_pago)FROM financeiro_recebimentos r WHERE r.clinica_id=current_clinica_id()AND r.status IN('pendente','atrasado')AND coalesce(r.previsto_credito_em,r.vencimento)=d::date AND(p_unidade IS NULL OR r.unidade_id=p_unidade)),0),coalesce((SELECT sum(p.valor-p.valor_pago)FROM financeiro_pagamentos p WHERE p.clinica_id=current_clinica_id()AND p.status IN('pendente','atrasado')AND p.vencimento=d::date AND(p_unidade IS NULL OR p.unidade_id=p_unidade)),0)FROM generate_series(p_inicio,p_fim,interval'1 day')d WHERE tem_papel('owner','admin','financeiro')ORDER BY d$$;
REVOKE EXECUTE ON FUNCTION public.apurar_comissoes(date),public.mudar_status_comissao(uuid,text),public.importar_extrato(uuid,text,text,jsonb),public.sugerir_conciliacao(uuid),public.conciliar_extrato(uuid,uuid,text),public.relatorio_dre(date,date,uuid,text),public.relatorio_fluxo_caixa(date,date,uuid)FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.apurar_comissoes(date),public.mudar_status_comissao(uuid,text),public.importar_extrato(uuid,text,text,jsonb),public.sugerir_conciliacao(uuid),public.conciliar_extrato(uuid,uuid,text),public.relatorio_dre(date,date,uuid,text),public.relatorio_fluxo_caixa(date,date,uuid)TO authenticated;